SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_114973c165158517>
    <urn:graphragprov:unit:u_171a6300ab9605bc>
    <urn:graphragprov:unit:u_97790632217aa4fe>
    <urn:graphragprov:unit:u_b8d66438a74b9c9f>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
